function(container, apiUrl, tables) {
  const clientTbody = container.querySelector("#client-tbody");
  const timelineContainer = container.querySelector("#timeline-container");
  const policyPanel = container.querySelector("#policy-panel");
  const interactionForm = container.querySelector("#new-interaction-form");

  let selectedClientId = null;
  let allClients = [];
  let allInteractions = [];
  let allPolicies = [];

  // ===== 1. クライアント一覧を描画 =====
  function renderClients(clients) {
    clientTbody.innerHTML = clients.map(c => `
      <tr 
        data-id="${c.id}" 
        class="client-row" 
        style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.08); padding: 8px; transition: background 0.15s;"
      >
        <td style="padding: 8px; font-size: 12px; color: var(--text);">
          <div style="font-weight: 500;">${c.client_name || "（名前なし）"}</div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${c.status || ""}</div>
        </td>
      </tr>
    `).join("");

    // クライアント行クリックで選択
    container.querySelectorAll(".client-row").forEach(row => {
      row.addEventListener("click", () => {
        container.querySelectorAll(".client-row").forEach(r => r.style.background = "transparent");
        row.style.background = "rgba(255,165,0,0.15)";
        selectedClientId = row.dataset.id;
        renderTimeline();
        renderPolicy();
      });
    });
  }

  // ===== 2. 対応履歴タイムラインを描画 =====
  function renderTimeline() {
    if (!selectedClientId) {
      timelineContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 20px;">クライアントを選択してください</div>';
      return;
    }

    const interactions = allInteractions.filter(i => i.client_id === selectedClientId).sort((a, b) => new Date(b.interaction_date) - new Date(a.interaction_date));

    if (interactions.length === 0) {
      timelineContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px; padding: 20px;">対応履歴がありません</div>';
      return;
    }

    timelineContainer.innerHTML = interactions.map((inter, idx) => {
      const date = new Date(inter.interaction_date);
      const dateStr = date.toLocaleDateString("ja-JP", { month: "2-digit", day: "2-digit" });
      const timeStr = date.toLocaleTimeString("ja-JP", { hour: "2-digit", minute: "2-digit" });

      return `
        <div style="display: flex; gap: 8px; margin-bottom: 12px; position: relative;">
          <div style="width: 2px; background: var(--primary); flex-shrink: 0; ${idx === interactions.length - 1 ? "height: 20px;" : "flex: 1;"}"></div>
          <div style="flex: 1; padding: 8px; border: 1px solid rgba(255,165,0,0.3); border-radius: 3px; background: rgba(255,165,0,0.08);">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
              <div style="font-weight: 600; font-size: 11px; color: var(--text);">${inter.interaction_type || "対応"}</div>
              <div style="font-size: 10px; color: var(--text-muted);">${dateStr} ${timeStr}</div>
            </div>
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">対応者: ${inter.user_name || "（未設定）"}</div>
            ${inter.result ? `<div style="font-size: 10px; color: var(--primary); margin-bottom: 4px;">結果: ${inter.result}</div>` : ""}
            <div style="font-size: 11px; color: var(--text); line-height: 1.4; white-space: pre-wrap; word-break: break-word;">${inter.content || ""}</div>
            <div style="display: flex; gap: 4px; margin-top: 6px;">
              <button class="action-btn secondary edit-interaction-btn" data-id="${inter.id}" style="padding: 3px 8px; font-size: 10px;">編集</button>
              <button class="action-btn secondary delete-interaction-btn" data-id="${inter.id}" style="padding: 3px 8px; font-size: 10px;">削除</button>
            </div>
          </div>
        </div>
      `;
    }).join("");
  }

  // ===== 3. 対応方針を表示 =====
  function renderPolicy() {
    if (!selectedClientId) {
      policyPanel.innerHTML = '<div style="text-align: center; padding: 8px; color: var(--text-muted);">方針情報なし</div>';
      return;
    }

    const policy = allPolicies.find(p => p.client_id === selectedClientId && p.status === "有効");

    if (!policy) {
      policyPanel.innerHTML = '<div style="text-align: center; padding: 8px; color: var(--text-muted);">対応方針が設定されていません</div>';
      return;
    }

    policyPanel.innerHTML = `
      <div style="padding: 6px; border-left: 3px solid var(--primary); background: rgba(255,165,0,0.08);">
        <div style="font-weight: 600; font-size: 11px; color: var(--text); margin-bottom: 4px;">${policy.policy_name || "方針"}</div>
        <div style="font-size: 10px; color: var(--text-muted); line-height: 1.4; margin-bottom: 4px;">${policy.policy_content || ""}</div>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 4px; font-size: 9px; color: var(--text-muted);">
          <div>優先度: <span style="color: var(--text);">${["高", "中", "低"][policy.priority - 1] || "中"}</span></div>
          <div>頻度: <span style="color: var(--text);">${policy.frequency || "未設定"}</span></div>
        </div>
      </div>
    `;
  }

  // ===== 4. 初期データ読み込み =====
  async function loadData() {
    // クライアント一覧
    const clients = await window.aivicApi.list(1); // テーブルインデックス 1 = クライアント
    allClients = clients || [];
    renderClients(allClients);

    // 対応履歴
    const interactions = await window.aivicApi.list(2); // テーブルインデックス 2 = 対応履歴
    allInteractions = interactions || [];

    // 対応方針
    const policies = await window.aivicApi.list(3); // テーブルインデックス 3 = 対応方針
    allPolicies = policies || [];
  }

  // ===== 5. クライアント検索 =====
  container.querySelector("#client-search-btn").addEventListener("click", async () => {
    const keyword = container.querySelector("#client-search-input").value.toLowerCase();
    const filtered = allClients.filter(c => 
      (c.client_name || "").toLowerCase().includes(keyword) ||
      (c.status || "").toLowerCase().includes(keyword)
    );
    renderClients(filtered);
  });

  // ===== 6. 新規対応記録 =====
  interactionForm.addEventListener("submit", async (e) => {
    e.preventDefault();

    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }

    const formData = new FormData(interactionForm);
    const newInteraction = {
      client_id: selectedClientId,
      user_id: formData.get("user_id"),
      interaction_type: formData.get("interaction_type"),
      interaction_date: formData.get("interaction_date"),
      content: formData.get("content"),
      result: formData.get("result"),
      status: "完了"
    };

    const saved = await window.aivicApi.save(2, newInteraction); // テーブルインデックス 2 = 対応履歴
    if (saved) {
      interactionForm.reset();
      const interactions = await window.aivicApi.list(2);
      allInteractions = interactions || [];
      renderTimeline();
    }
  });

  // ===== 7. 対応履歴の削除 =====
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-interaction-btn");
    if (deleteBtn) {
      if (!confirm("この対応履歴を削除しますか？")) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(2, id); // テーブルインデックス 2 = 対応履歴
      const interactions = await window.aivicApi.list(2);
      allInteractions = interactions || [];
      renderTimeline();
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=対応履歴, 1=クライアント, 2=案件, 3=対応方針, 4=受注
  const contactHistoryIndex = 0;
  const clientIndex = 1;
  const projectIndex = 2;
  const policyIndex = 3;
  const orderIndex = 4;

  // フォーム要素の取得
  const clientSelect = container.querySelector("#client-select");
  const projectSelect = container.querySelector("#project-select");
  const contactDatetime = container.querySelector("#contact-datetime");
  const contactMethod = container.querySelector("#contact-method");
  const contactContent = container.querySelector("#contact-content");
  const policySelect = container.querySelector("#policy-select");
  const nextContactDate = container.querySelector("#next-contact-date");
  const fileInput = container.querySelector("#file-input");
  const fileDropZone = container.querySelector("#file-drop-zone");
  const fileList = container.querySelector("#file-list");
  const currentUserDisplay = container.querySelector("#current-user");
  const btnSave = container.querySelector("#btn-save");
  const btnCancel = container.querySelector("#btn-cancel");
  const historyTimeline = container.querySelector("#history-timeline");
  const btnViewOrder = container.querySelector("#btn-view-order");

  // ファイル選択状態
  let selectedFiles = [];

  // 1. 初期データ描画
  function renderClients() {
    const clients = tables[clientIndex]?.records || [];
    clientSelect.innerHTML = '<option value="">選択してください</option>';
    clients.forEach(c => {
      const opt = document.createElement("option");
      opt.value = c.id || c.クライアントID;
      opt.textContent = c.クライアント名 || c.name || "無名";
      clientSelect.appendChild(opt);
    });
  }

  function renderProjects() {
    const projects = tables[projectIndex]?.records || [];
    projectSelect.innerHTML = '<option value="">選択してください</option>';
    projects.forEach(p => {
      const opt = document.createElement("option");
      opt.value = p.id || p.案件ID;
      opt.textContent = p.案件名 || p.name || "無名";
      projectSelect.appendChild(opt);
    });
  }

  function renderPolicies() {
    const policies = tables[policyIndex]?.records || [];
    policySelect.innerHTML = '<option value="">選択してください</option>';
    policies.forEach(pol => {
      const opt = document.createElement("option");
      opt.value = pol.id || pol.対応方針ID;
      opt.textContent = pol.対応方針名 || pol.方針名 || "無名";
      policySelect.appendChild(opt);
    });
  }

  function renderHistoryTimeline(clientId) {
    const histories = tables[contactHistoryIndex]?.records || [];
    const filtered = histories.filter(h => h.クライアントID === clientId || h.clientId === clientId).slice(0, 5);

    historyTimeline.innerHTML = filtered.length === 0 
      ? '<p style="font-size: 0.8125rem; color: var(--text-muted); text-align: center; padding: 1rem;">対応履歴がありません</p>'
      : filtered.map(h => {
          const methodColor = h.対応種別 === "電話" ? "var(--primary)" 
                            : h.対応種別 === "メール" ? "rgba(255,165,0,0.6)"
                            : h.対応種別 === "訪問" ? "rgba(100,200,100,0.6)"
                            : "rgba(150,150,150,0.6)";
          return `
            <div style="padding: 0.75rem; background: rgba(0,0,0,0.15); border-radius: 0.375rem; border-left: 3px solid ${methodColor};">
              <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 0.375rem;">
                <span style="font-size: 0.8125rem; font-weight: 500; color: var(--text);">${h.対応種別 || h.contactMethod || "未分類"}</span>
                <span style="font-size: 0.75rem; color: var(--text-muted);">${h.対応日時 ? new Date(h.対応日時).toLocaleString('ja-JP', {year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit'}) : "日時未設定"}</span>
              </div>
              <p style="font-size: 0.8125rem; color: var(--text-muted); margin: 0;">${(h.対応内容 || h.content || "").substring(0, 80)}${(h.対応内容 || h.content || "").length > 80 ? "..." : ""}</p>
            </div>
          `;
        }).join("");
  }

  renderClients();
  renderProjects();
  renderPolicies();
  renderHistoryTimeline("");

  // 2. クライアント選択時に履歴を更新
  clientSelect.addEventListener("change", (e) => {
    renderHistoryTimeline(e.target.value);
  });

  // 3. ファイルドラッグ&ドロップ
  fileDropZone.addEventListener("dragover", (e) => {
    e.preventDefault();
    fileDropZone.style.borderColor = "var(--primary)";
    fileDropZone.style.background = "rgba(255,165,0,0.05)";
  });

  fileDropZone.addEventListener("dragleave", () => {
    fileDropZone.style.borderColor = "rgba(255,255,255,0.18)";
    fileDropZone.style.background = "transparent";
  });

  fileDropZone.addEventListener("drop", (e) => {
    e.preventDefault();
    fileDropZone.style.borderColor = "rgba(255,255,255,0.18)";
    fileDropZone.style.background = "transparent";
    selectedFiles = Array.from(e.dataTransfer.files);
    updateFileList();
  });

  fileDropZone.addEventListener("click", () => fileInput.click());

  fileInput.addEventListener("change", (e) => {
    selectedFiles = Array.from(e.target.files);
    updateFileList();
  });

  function updateFileList() {
    fileList.innerHTML = selectedFiles.map((f, i) => 
      `<div style="display: flex; justify-content: space-between; align-items: center; padding: 0.25rem 0;">
        <span>${f.name} (${(f.size / 1024).toFixed(1)} KB)</span>
        <button type="button" style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 0.75rem;" onclick="this.parentElement.remove();">削除</button>
      </div>`
    ).join("");
  }

  // 4. 登録ボタン
  btnSave.addEventListener("click", async () => {
    const clientId = clientSelect.value;
    const projectId = projectSelect.value;
    const datetime = contactDatetime.value;
    const method = contactMethod.value;
    const content = contactContent.value;
    const policyId = policySelect.value;
    const nextDate = nextContactDate.value;

    if (!clientId || !datetime || !method || !content) {
      alert("必須項目を入力してください");
      return;
    }

    const payload = {
      クライアントID: clientId,
      案件ID: projectId || null,
      対応日時: new Date(datetime).toISOString(),
      対応種別: method,
      対応内容: content,
      対応方針ID: policyId || null,
      次回対応予定日: nextDate ? new Date(nextDate).toISOString() : null,
      ステータス: "完了",
      ユーザーID: "current-user-id"
    };

    const saved = await window.aivicApi.save(contactHistoryIndex, payload);
    if (saved) {
      alert("対応履歴を登録しました");
      // フォームリセット
      clientSelect.value = "";
      projectSelect.value = "";
      contactDatetime.value = "";
      contactMethod.value = "";
      contactContent.value = "";
      policySelect.value = "";
      nextContactDate.value = "";
      selectedFiles = [];
      fileList.innerHTML = "";
      renderHistoryTimeline("");
    }
  });

  // 5. キャンセルボタン
  btnCancel.addEventListener("click", () => {
    if (confirm("入力内容を破棄してクライアント統合ダッシュボードに戻りますか？")) {
      window.showScreen("scr-1781408811435");
    }
  });

  // 6. 受注詳細ボタン
  btnViewOrder.addEventListener("click", () => {
    window.showScreen("scr-1781408853048");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=クライアント, 1=対応方針, 2=対応履歴, 3=案件
  const clientTable = tables[0] || { records: [] };
  const policyTable = tables[1] || { records: [] };
  const historyTable = tables[2] || { records: [] };
  const projectTable = tables[3] || { records: [] };

  let selectedClientId = null;
  let selectedPolicyId = null;

  // ===== 1. クライアント一覧の描画 =====
  function renderClientList(clients) {
    const clientList = container.querySelector("#client-list");
    clientList.innerHTML = clients.map(client => {
      const policy = policyTable.records.find(p => p.クライアントID === client.クライアントID);
      const statusBadge = policy 
        ? `<span style="display: inline-block; font-size: 10px; padding: 2px 6px; border-radius: 3px; background: var(--primary); color: #fff; margin-left: 4px;">${policy['対応方針ステータス'] || '有効'}</span>`
        : `<span style="display: inline-block; font-size: 10px; padding: 2px 6px; border-radius: 3px; background: rgba(255,255,255,0.1); color: var(--text-muted); margin-left: 4px;">未設定</span>`;

      return `
        <div 
          class="client-item" 
          data-id="${client.クライアントID}" 
          style="padding: 8px 12px; border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; transition: background 0.2s; background: ${selectedClientId === client.クライアントID ? 'rgba(255,255,255,0.08)' : 'transparent'};"
        >
          <div style="font-size: 12px; font-weight: 500; color: var(--text);">${client.クライアント名 || '（名前未設定）'}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${client.業種 || '業種未設定'}</div>
          ${statusBadge}
        </div>
      `;
    }).join("");

    // クライアント選択イベント
    container.querySelectorAll(".client-item").forEach(item => {
      item.addEventListener("click", () => {
        selectedClientId = item.dataset.id;
        selectedPolicyId = null;
        renderClientList(clients); // 選択状態を再描画
        loadPolicyForClient(selectedClientId);
      });
    });
  }

  // ===== 2. クライアント選択時の対応方針ロード =====
  function loadPolicyForClient(clientId) {
    const policy = policyTable.records.find(p => p.クライアントID === clientId);
    const selectedInfo = container.querySelector("#selected-client-info");
    const selectedName = container.querySelector("#selected-client-name");
    const client = clientTable.records.find(c => c.クライアントID === clientId);

    if (client) {
      selectedName.textContent = client.クライアント名;
      selectedInfo.style.display = "block";
    }

    // フォームをリセット
    container.querySelector("#policy-name").value = policy?.['対応方針名'] || "";
    container.querySelector("#policy-description").value = policy?.['対応方針説明'] || "";
    container.querySelector("#contact-frequency").value = policy?.['対応頻度'] || "";
    container.querySelector("#start-date").value = policy?.['開始日'] ? policy['開始日'].split('T')[0] : "";
    container.querySelector("#end-date").value = policy?.['終了日'] ? policy['終了日'].split('T')[0] : "";

    // 優先度ラジオボタン
    if (policy?.['優先度']) {
      container.querySelector(`input[name="priority"][value="${policy['優先度']}"]`).checked = true;
    } else {
      container.querySelectorAll(`input[name="priority"]`).forEach(r => r.checked = false);
    }

    // チャネルチェックボックス
    container.querySelectorAll(`input[name="channel"]`).forEach(cb => cb.checked = false);
    if (policy?.['対応チャネル']) {
      const channels = policy['対応チャネル'].split(',');
      channels.forEach(ch => {
        const cb = container.querySelector(`input[name="channel"][value="${ch.trim()}"]`);
        if (cb) cb.checked = true;
      });
    }

    // 担当営業者マルチセレクト
    container.querySelectorAll("#assigned-users option").forEach(opt => opt.selected = false);
    if (policy?.['営業担当者ID']) {
      const userIds = policy['営業担当者ID'].split(',');
      userIds.forEach(uid => {
        const opt = container.querySelector(`#assigned-users option[value="${uid.trim()}"]`);
        if (opt) opt.selected = true;
      });
    }

    selectedPolicyId = policy?.['対応方針ID'] || null;

    // 過去対応履歴を描画
    renderHistoryTimeline(clientId);

    // 関連案件を描画
    renderRelatedProjects(clientId);
  }

  // ===== 3. 過去対応履歴タイムライン =====
  function renderHistoryTimeline(clientId) {
    const histories = historyTable.records.filter(h => h.クライアントID === clientId).slice(0, 5);
    const timeline = container.querySelector("#history-timeline");
    const empty = container.querySelector("#history-empty");

    if (histories.length === 0) {
      timeline.innerHTML = "";
      empty.style.display = "block";
      return;
    }

    empty.style.display = "none";
    timeline.innerHTML = histories.map(h => `
      <div style="display: flex; gap: 8px; padding: 8px; background: rgba(255,255,255,0.04); border-radius: 4px; border-left: 2px solid var(--primary);">
        <div style="flex-shrink: 0; width: 4px; background: var(--primary); border-radius: 2px;"></div>
        <div style="flex: 1;">
          <div style="font-size: 11px; font-weight: 500; color: var(--text);">${h.対応種別 || '対応'}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">${h.対応内容?.substring(0, 50) || '内容なし'}...</div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">${new Date(h.対応日時).toLocaleDateString('ja-JP')}</div>
        </div>
      </div>
    `).join("");
  }

  // ===== 4. 関連案件テーブル =====
  function renderRelatedProjects(clientId) {
    const projects = projectTable.records.filter(p => p.クライアントID === clientId);
    const tbody = container.querySelector("#projects-tbody");
    const empty = container.querySelector("#projects-empty");

    if (projects.length === 0) {
      tbody.innerHTML = "";
      empty.style.display = "block";
      return;
    }

    empty.style.display = "none";
    tbody.innerHTML = projects.map(p => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05); hover: background rgba(255,255,255,0.04);">
        <td style="padding: 8px; color: var(--text);">${p.案件名 || '（未設定）'}</td>
        <td style="padding: 8px; color: var(--text-muted);">${p.ステータス || '未設定'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${(p.予想金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${p.成約確度 || 0}%</td>
      </tr>
    `).join("");
  }

  // ===== 5. 保存ボタン =====
  container.querySelector("#btn-save").addEventListener("click", async () => {
    if (!selectedClientId) {
      alert("クライアントを選択してください");
      return;
    }

    const policyName = container.querySelector("#policy-name").value.trim();
    const policyDesc = container.querySelector("#policy-description").value.trim();
    const priority = container.querySelector('input[name="priority"]:checked')?.value;
    const frequency = container.querySelector("#contact-frequency").value;
    const startDate = container.querySelector("#start-date").value;
    const channels = Array.from(container.querySelectorAll('input[name="channel"]:checked')).map(cb => cb.value).join(',');
    const users = Array.from(container.querySelector("#assigned-users").selectedOptions).map(opt => opt.value).join(',');

    if (!policyName || !policyDesc || !priority || !startDate) {
      alert("必須項目を入力してください");
      return;
    }

    const payload = {
      クライアントID: selectedClientId,
      対応方針名: policyName,
      対応方針説明: policyDesc,
      優先度: parseInt(priority),
      対応頻度: frequency,
      対応チャネル: channels,
      営業担当者ID: users,
      開始日: startDate,
      終了日: container.querySelector("#end-date").value || null,
      対応方針ステータス: "有効"
    };

    if (selectedPolicyId) {
      // 更新
      const updated = await window.aivicApi.update(1, selectedPolicyId, payload);
      if (updated) {
        alert("対応方針を更新しました");
        const updated_policies = await window.aivicApi.list(1);
        policyTable.records = updated_policies || [];
        renderClientList(clientTable.records);
        loadPolicyForClient(selectedClientId);
      }
    } else {
      // 新規保存
      const saved = await window.aivicApi.save(1, payload);
      if (saved) {
        alert("対応方針を保存しました");
        const updated_policies = await window.aivicApi.list(1);
        policyTable.records = updated_policies || [];
        renderClientList(clientTable.records);
        loadPolicyForClient(selectedClientId);
      }
    }
  });

  // ===== 6. キャンセルボタン =====
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    selectedClientId = null;
    selectedPolicyId = null;
    container.querySelector("#selected-client-info").style.display = "none";
    container.querySelectorAll("input, textarea, select").forEach(el => {
      if (el.type === "radio" || el.type === "checkbox") el.checked = false;
      else if (el.tagName === "SELECT") el.value = "";
      else el.value = "";
    });
  });

  // ===== 7. クライアント検索 =====
  container.querySelector("#client-search").addEventListener("input", (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = clientTable.records.filter(c => 
      c.クライアント名?.toLowerCase().includes(keyword) || 
      c.業種?.toLowerCase().includes(keyword)
    );
    renderClientList(filtered);
  });

  // ===== 8. 初期描画 =====
  renderClientList(clientTable.records);
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 受注テーブル(0), クライアント(1), ユーザー(2)
  const orderTable = tables[0] || { records: [] };
  const clientTable = tables[1] || { records: [] };
  const userTable = tables[2] || { records: [] };

  // 初期データ
  let allOrders = orderTable.records || [];
  let allClients = clientTable.records || [];
  let allUsers = userTable.records || [];

  // DOM 要素
  const orderTbody = container.querySelector('#order-tbody');
  const resultCount = container.querySelector('[data-testid="result-count"]');
  const clientPanel = container.querySelector('#client-panel');
  const noSelection = container.querySelector('#no-selection');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const viewDetailBtn = container.querySelector('[data-testid="view-client-detail"]');

  // フィルタ入力
  const clientNameInput = container.querySelector('[data-testid="client-name-input"]');
  const orderDateFrom = container.querySelector('[data-testid="order-date-from"]');
  const orderDateTo = container.querySelector('[data-testid="order-date-to"]');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');
  const projectNameInput = container.querySelector('[data-testid="project-name-input"]');
  const salespersonFilter = container.querySelector('[data-testid="salesperson-filter"]');
  const amountMin = container.querySelector('[data-testid="amount-min"]');
  const amountMax = container.querySelector('[data-testid="amount-max"]');

  // 選択中の受注ID
  let selectedOrderId = null;

  // ユーザーID → 氏名マップ
  function getUserName(userId) {
    const user = allUsers.find(u => u.ユーザーID === userId || u.id === userId);
    return user ? (user.氏名 || user.name || '—') : '—';
  }

  // クライアントID → クライアント情報マップ
  function getClient(clientId) {
    return allClients.find(c => c.クライアントID === clientId || c.id === clientId);
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '—';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit' });
  }

  // 金額フォーマット
  function formatAmount(amount) {
    if (!amount) return '¥0';
    return '¥' + amount.toLocaleString('ja-JP');
  }

  // 受注一覧を再描画
  function renderOrders(orders) {
    orderTbody.innerHTML = orders.map(order => {
      const clientId = order.クライアントID || order.clientId;
      const client = getClient(clientId);
      const clientName = client ? (client.クライアント名 || client.name || '—') : '—';
      const salesUserId = order.営業担当者ID || order.salespersonId;
      const salesName = getUserName(salesUserId);
      const orderId = order.受注ID || order.id;
      const orderDate = formatDate(order.受注日 || order.orderDate);
      const amount = order.受注金額 || order.amount || 0;
      const status = order.ステータス || order.status || '—';
      const productName = order['商品・サービス名'] || order.productName || '—';

      return `<tr data-id="${orderId}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background=''">
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">${orderId.substring(0, 8)}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">${clientName}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">${orderDate}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">${productName}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem; text-align: right; font-weight: 500;">${formatAmount(amount)}</td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${status === '完了' ? 'rgba(34,197,94,0.15)' : status === 'キャンセル' ? 'rgba(239,68,68,0.15)' : 'rgba(59,130,246,0.15)'}; color: ${status === '完了' ? '#22c55e' : status === 'キャンセル' ? '#ef4444' : '#3b82f6'};">${status}</span>
        </td>
        <td style="padding: 0.75rem; color: var(--text); font-size: 0.8125rem;">${salesName}</td>
      </tr>`;
    }).join('');
    resultCount.textContent = orders.length;
  }

  // クライアント情報パネルを表示
  function showClientPanel(orderId) {
    const order = allOrders.find(o => (o.受注ID || o.id) === orderId);
    if (!order) return;

    const clientId = order.クライアントID || order.clientId;
    const client = getClient(clientId);

    if (!client) {
      clientPanel.style.display = 'none';
      noSelection.style.display = 'block';
      return;
    }

    container.querySelector('#panel-client-name').textContent = client.クライアント名 || client.name || '—';
    container.querySelector('#panel-industry').textContent = client.業種 || client.industry || '—';
    container.querySelector('#panel-representative').textContent = client.代表者名 || client.representative || '—';
    container.querySelector('#panel-email').textContent = client.メールアドレス || client.email || '—';
    container.querySelector('#panel-phone').textContent = client.電話番号 || client.phone || '—';
    container.querySelector('#panel-address').textContent = client.住所 || client.address || '—';
    container.querySelector('#panel-status').textContent = client.ステータス || client.status || '—';
    container.querySelector('#panel-last-contact').textContent = formatDate(client.最終接触日 || client.lastContactDate);

    clientPanel.style.display = 'block';
    noSelection.style.display = 'none';
    selectedOrderId = orderId;
  }

  // 検索実行
  function performSearch() {
    const clientName = clientNameInput.value.toLowerCase();
    const dateFrom = orderDateFrom.value ? new Date(orderDateFrom.value) : null;
    const dateTo = orderDateTo.value ? new Date(orderDateTo.value + 'T23:59:59') : null;
    const status = statusFilter.value;
    const projectName = projectNameInput.value.toLowerCase();
    const salesperson = salespersonFilter.value;
    const minAmount = amountMin.value ? parseInt(amountMin.value) : null;
    const maxAmount = amountMax.value ? parseInt(amountMax.value) : null;

    const filtered = allOrders.filter(order => {
      const clientId = order.クライアントID || order.clientId;
      const client = getClient(clientId);
      const orderClientName = (client ? (client.クライアント名 || client.name) : '').toLowerCase();

      if (clientName && !orderClientName.includes(clientName)) return false;

      const orderDate = new Date(order.受注日 || order.orderDate);
      if (dateFrom && orderDate < dateFrom) return false;
      if (dateTo && orderDate > dateTo) return false;

      if (status && (order.ステータス || order.status) !== status) return false;

      const productName = (order['商品・サービス名'] || order.productName || '').toLowerCase();
      if (projectName && !productName.includes(projectName)) return false;

      if (salesperson) {
        const salesUserId = order.営業担当者ID || order.salespersonId;
        const salesName = getUserName(salesUserId);
        if (salesName !== salesperson) return false;
      }

      const amount = order.受注金額 || order.amount || 0;
      if (minAmount !== null && amount < minAmount) return false;
      if (maxAmount !== null && amount > maxAmount) return false;

      return true;
    });

    renderOrders(filtered);
    clientPanel.style.display = 'none';
    noSelection.style.display = 'block';
    selectedOrderId = null;
  }

  // リセット
  function resetFilters() {
    clientNameInput.value = '';
    orderDateFrom.value = '';
    orderDateTo.value = '';
    statusFilter.value = '';
    projectNameInput.value = '';
    salespersonFilter.value = '';
    amountMin.value = '';
    amountMax.value = '';
    renderOrders(allOrders);
    clientPanel.style.display = 'none';
    noSelection.style.display = 'block';
    selectedOrderId = null;
  }

  // CSV エクスポート
  function exportCSV() {
    const headers = ['受注ID', 'クライアント名', '受注日', '商品・サービス名', '受注金額', 'ステータス', '営業担当者'];
    const rows = [];

    const visibleRows = container.querySelectorAll('#order-tbody tr');
    visibleRows.forEach(tr => {
      const cells = tr.querySelectorAll('td');
      rows.push([
        cells[0].textContent,
        cells[1].textContent,
        cells[2].textContent,
        cells[3].textContent,
        cells[4].textContent,
        cells[5].textContent,
        cells[6].textContent
      ]);
    });

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${cell.replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `order_history_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // イベントリスナー
  searchBtn.addEventListener('click', performSearch);
  resetBtn.addEventListener('click', resetFilters);
  exportBtn.addEventListener('click', exportCSV);

  // 行クリックでクライアント情報表示
  container.addEventListener('click', e => {
    const tr = e.target.closest('#order-tbody tr');
    if (tr) {
      const orderId = tr.dataset.id;
      showClientPanel(orderId);
    }
  });

  // 詳細ボタン
  viewDetailBtn.addEventListener('click', () => {
    if (selectedOrderId) {
      const order = allOrders.find(o => (o.受注ID || o.id) === selectedOrderId);
      if (order) {
        const clientId = order.クライアントID || order.clientId;
        window.showScreen('scr-1781408824557', { clientId });
      }
    }
  });

  // 初期表示
  renderOrders(allOrders);
}

