function(container, apiUrl, tables) {
  // テーブルインデックス
  const clientTableIdx = tables.findIndex(t => t.tableName === 'ユーザー') >= 0 ? 0 : 0;
  const clientIdx = tables.findIndex(t => t.tableName === 'クライアント') >= 0 ? tables.findIndex(t => t.tableName === 'クライアント') : 1;
  const historyIdx = tables.findIndex(t => t.tableName === '対応履歴') >= 0 ? tables.findIndex(t => t.tableName === '対応履歴') : 2;
  const projectIdx = tables.findIndex(t => t.tableName === '案件') >= 0 ? tables.findIndex(t => t.tableName === '案件') : 3;
  const orderIdx = tables.findIndex(t => t.tableName === '受注') >= 0 ? tables.findIndex(t => t.tableName === '受注') : 4;

  // 日付表示
  const today = new Date();
  container.querySelector('#current-date').textContent = 
    `${today.getFullYear()}年${today.getMonth() + 1}月${today.getDate()}日`;

  // ===== 1. クライアント一覧の再描画 =====
  function renderClients(rows) {
    const tbody = container.querySelector('#client-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.slice(0, 10).map(r => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);" data-id="${r.id || r.クライアントID}">
        <td style="padding: 6px; color: var(--text);">${r.クライアント名 || r.name || ''}</td>
        <td style="padding: 6px; color: var(--text-muted); font-size: 11px;">${r.ステータス || r.status || '未設定'}</td>
        <td style="padding: 6px; text-align: center;">
          <button class="action-btn secondary client-detail-btn" data-id="${r.id || r.クライアントID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // ===== 2. 案件進捗ボード（カンバン） =====
  function renderKanban(rows) {
    const newDiv = container.querySelector('#kanban-new');
    const progressDiv = container.querySelector('#kanban-progress');
    const wonDiv = container.querySelector('#kanban-won');
    newDiv.innerHTML = '';
    progressDiv.innerHTML = '';
    wonDiv.innerHTML = '';

    if (!rows) rows = [];
    rows.forEach(r => {
      const status = r.ステータス || r.status || '新規';
      const name = r.案件名 || r.name || '案件';
      const amount = r.予想金額 || r.amount || 0;
      const card = `
        <div style="background: var(--bg-card); padding: 6px; border-radius: 4px; border-left: 3px solid var(--primary); cursor: pointer; font-size: 11px;">
          <div style="font-weight: 600; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${name}</div>
          <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">¥${(amount || 0).toLocaleString()}</div>
        </div>
      `;
      if (status === '新規') newDiv.innerHTML += card;
      else if (status === '進行中') progressDiv.innerHTML += card;
      else if (status === '受注') wonDiv.innerHTML += card;
    });
  }

  // ===== 3. 対応履歴タイムライン =====
  function renderTimeline(rows) {
    const container_tl = container.querySelector('#timeline-container');
    if (!rows || rows.length === 0) {
      container_tl.innerHTML = '<div style="color: var(--text-muted); padding: 12px; text-align: center;">対応履歴なし</div>';
      return;
    }
    container_tl.innerHTML = rows.slice(0, 5).map(r => {
      const date = r.対応日時 ? new Date(r.対応日時).toLocaleDateString('ja-JP') : '日付不明';
      const type = r.対応種別 || r.type || '対応';
      const content = r.対応内容 || r.content || '';
      return `
        <div style="padding: 8px; border-left: 3px solid var(--primary); background: rgba(0,0,0,0.1); border-radius: 4px;">
          <div style="font-weight: 600; color: var(--text); font-size: 11px;">${type}</div>
          <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">${date}</div>
          <div style="color: var(--text); font-size: 11px; margin-top: 4px; line-height: 1.4;">${content.substring(0, 60)}${content.length > 60 ? '...' : ''}</div>
        </div>
      `;
    }).join('');
  }

  // ===== 4. KPI 計算 =====
  function updateKPIs(clients, orders, projects, histories) {
    // 今月受注額
    const thisMonth = new Date();
    thisMonth.setDate(1);
    const monthOrders = (orders || []).filter(o => {
      const oDate = new Date(o.受注日 || o.date || 0);
      return oDate >= thisMonth;
    });
    const totalRevenue = monthOrders.reduce((sum, o) => sum + (o.受注金額 || o.amount || 0), 0);
    container.querySelector('[data-testid="kpi-revenue"]').textContent = `¥${totalRevenue.toLocaleString()}`;
    container.querySelector('#kpi-count').textContent = monthOrders.length;

    // 進行中案件
    const progressProjects = (projects || []).filter(p => p.ステータス === '進行中' || p.status === 'progress');
    const projectAmount = progressProjects.reduce((sum, p) => sum + (p.予想金額 || p.amount || 0), 0);
    container.querySelector('[data-testid="kpi-projects"]').textContent = progressProjects.length;
    container.querySelector('#kpi-project-amount').textContent = `¥${projectAmount.toLocaleString()}`;

    // 顧客数
    const existingClients = (clients || []).filter(c => c.ステータス === '既存顧客' || c.status === 'existing');
    container.querySelector('[data-testid="kpi-clients"]').textContent = (clients || []).length;
    container.querySelector('#kpi-existing').textContent = existingClients.length;

    // 対応待ち（次回対応予定日が今日以前のもの）
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const pending = (histories || []).filter(h => {
      const nextDate = new Date(h.次回対応予定日 || h.nextDate || '2099-01-01');
      return nextDate <= today && (h.ステータス !== '完了' && h.status !== 'completed');
    });
    container.querySelector('[data-testid="kpi-pending"]').textContent = pending.length;

    // 受注状況サマリー
    const confirmed = (orders || []).filter(o => o.ステータス === '受注確定' || o.status === 'confirmed').length;
    const orderPending = (orders || []).filter(o => o.ステータス === '納品待ち' || o.status === 'pending').length;
    const completed = (orders || []).filter(o => o.ステータス === '完了' || o.status === 'completed').length;
    const cancelled = (orders || []).filter(o => o.ステータス === 'キャンセル' || o.status === 'cancelled').length;
    container.querySelector('#summary-confirmed').textContent = confirmed;
    container.querySelector('#summary-pending').textContent = orderPending;
    container.querySelector('#summary-completed').textContent = completed;
    container.querySelector('#summary-cancelled').textContent = cancelled;
  }

  // ===== 5. 売上予測チャート（Canvas） =====
  function drawRevenueChart(orders) {
    const canvas = container.querySelector('#revenue-chart');
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;

    // 背景
    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.fillRect(0, 0, width, height);

    // 今月のデータ
    const thisMonth = new Date();
    thisMonth.setDate(1);
    const nextMonth = new Date(thisMonth);
    nextMonth.setMonth(nextMonth.getMonth() + 1);

    const monthOrders = (orders || []).filter(o => {
      const oDate = new Date(o.受注日 || o.date || 0);
      return oDate >= thisMonth && oDate < nextMonth;
    });

    // 日ごとの集計
    const dailyData = {};
    monthOrders.forEach(o => {
      const date = new Date(o.受注日 || o.date || 0);
      const day = date.getDate();
      dailyData[day] = (dailyData[day] || 0) + (o.受注金額 || o.amount || 0);
    });

    const days = Object.keys(dailyData).map(Number).sort((a, b) => a - b);
    if (days.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.fillText('データなし', width / 2 - 30, height / 2);
      return;
    }

    const maxValue = Math.max(...Object.values(dailyData));
    const barWidth = Math.max(2, (width - 40) / Math.max(days.length, 10));
    const padding = 20;

    // Y 軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(`¥${(maxValue / 1000000).toFixed(1)}M`, padding - 5, 15);
    ctx.fillText('¥0', padding - 5, height - padding + 5);

    // グリッド線
    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, 10);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - 10, height - padding);
    ctx.stroke();

    // バー描画
    ctx.fillStyle = '#ff6a00';
    days.forEach((day, idx) => {
      const value = dailyData[day];
      const barHeight = ((value / maxValue) * (height - padding - 20));
      const x = padding + idx * barWidth + 5;
      const y = height - padding - barHeight;
      ctx.fillRect(x, y, Math.max(1, barWidth - 2), barHeight);
    });

    // X 軸ラベル（最初と最後）
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(`${days[0]}日`, padding + 5, height - 5);
    if (days.length > 1) {
      ctx.fillText(`${days[days.length - 1]}日`, padding + (days.length - 1) * barWidth + 5, height - 5);
    }
  }

  // ===== 6. 初期データ読み込み =====
  async function loadDashboard() {
    try {
      const clients = tables[clientIdx]?.records || [];
      const histories = tables[historyIdx]?.records || [];
      const projects = tables[projectIdx]?.records || [];
      const orders = tables[orderIdx]?.records || [];

      renderClients(clients);
      renderKanban(projects);
      renderTimeline(histories);
      updateKPIs(clients, orders, projects, histories);
      drawRevenueChart(orders);
    } catch (e) {
      console.error('Dashboard load error:', e);
    }
  }

  loadDashboard();

  // ===== 7. クライアント検索 =====
  container.querySelector('#btn-search-client').addEventListener('click', async () => {
    const nameKw = container.querySelector('#search-client-name').value.toLowerCase();
    const statusFilter = container.querySelector('#search-status').value;

    try {
      const allClients = tables[clientIdx]?.records || [];
      const filtered = allClients.filter(c => {
        const nameMatch = (c.クライアント名 || c.name || '').toLowerCase().includes(nameKw);
        const statusMatch = !statusFilter || (c.ステータス || c.status) === statusFilter;
        return nameMatch && statusMatch;
      });
      renderClients(filtered);
    } catch (e) {
      console.error('Search error:', e);
    }
  });

  // ===== 8. クライアント詳細へ遷移 =====
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.client-detail-btn');
    if (detailBtn) {
      const clientId = detailBtn.dataset.id;
      window.showScreen('scr-1781408824557', { clientId });
    }

    const addHistoryBtn = e.target.closest('#btn-add-history');
    if (addHistoryBtn) {
      window.showScreen('scr-1781408865891');
    }

    const newProjectBtn = e.target.closest('#btn-new-project');
    if (newProjectBtn) {
      window.showScreen('scr-1781408904580');
    }
  });

  // ===== 9. ウィンドウリサイズ時にチャート再描画 =====
  window.addEventListener('resize', () => {
    const orders = tables[orderIdx]?.records || [];
    drawRevenueChart(orders);
  });
}
